import redis
import json
from typing import Optional, Dict, Any
import time

# Configuration constants
DEFAULT_HOST = 'localhost'
DEFAULT_PORT = 6379

class RedisCache:
    """A robust wrapper around Redis for caching and rate limiting."""
    def __init__(self, host: str = DEFAULT_HOST, port: int = DEFAULT_PORT, db: int = 0):
        try:
            self.redis_client = redis.Redis(host=host, port=port, db=db, decode_responses=True)
            # Test connection immediately
            self.redis_client.ping()
            print("RedisCache initialized successfully.")
        except redis.exceptions.ConnectionError as e:
            print(f"Error connecting to Redis at {host}:{port}: {e}")
            self.redis_client = None

    def is_connected(self) -> bool:
        """Checks if the Redis connection is active."""
        return self.redis_client is not None

    def set(self, key: str, value: Any, ex: int) -> bool:
        """Sets a key with an expiration time (in seconds)."""
        if not self.is_connected():
            return False
        try:
            return self.redis_client.set(key, json.dumps(value), ex=ex)
        except Exception as e:
            print(f"Error setting key {key}: {e}")
            return False

    def get(self, key: str) -> Optional[Any]:
        """Gets a key and attempts to deserialize it."""
        if not self.is_connected():
            return None
        try:
            value = self.redis_client.get(key)
            if value is None:
                return None
            return json.loads(value)
        except Exception as e:
            print(f"Error getting key {key}: {e}")
            return None

    def increment(self, key: str, amount: int = 1) -> int:
        """Atomically increments a counter and returns the new value."""
        if not self.is_connected():
            return -1 # Indicate failure
        try:
            return self.redis_client.incrby(key, amount)
        except Exception as e:
            print(f"Error incrementing key {key}: {e}")
            return -1

    def expire(self, key: str, seconds: int) -> bool:
        """Sets an expiration time on a key."""
        if not self.is_connected():
            return False
        try:
            return self.redis_client.expire(key, seconds)
        except Exception as e:
            print(f"Error expiring key {key}: {e}")
            return False

    def rate_limit(self, identifier: str, limit: int, window_seconds: int) -> bool:
        """Implements a fixed window rate limiter using Redis INCR and EXPIRE."""
        if not self.is_connected():
            # Fail open or fail closed based on security policy. Failing closed (returning False) is safer for rate limiting.
            print("Warning: Redis not connected. Rate limiting bypassed (Fail Closed).")
            return False # Block requests if cache is down

        # Key format: rate_limit:<identifier>:<window_start_timestamp>
        # We use the current window start time to ensure requests fall into the correct bucket.
        current_time = int(time.time() // window_seconds) * window_seconds
        key = f"rate_limit:{identifier}:{current_time}"

        try:
            # 1. Increment the counter
            current_count = self.redis_client.incr(key)

            # 2. Set expiration only if it's the first request in this window
            if current_count == 1:
                self.redis_client.expire(key, window_seconds)

            # 3. Check limit
            return current_count <= limit
        except Exception as e:
            print(f"Critical error during rate limiting for {identifier}: {e}")
            # Fail closed: if we can't check the limit, we block to prevent abuse.
            return False

# Example Usage (for testing purposes)
if __name__ == '__main__':
    # Ensure Redis is running on localhost:6379
    cache = RedisCache()

    if cache.is_connected():
        user_id = "user_123"
        limit = 5
        window = 60 # 60 seconds

        print(f"--- Testing Rate Limit ({limit} requests per {window}s) for {user_id} ---")

        # Test successful requests
        for i in range(1, limit + 1):
            allowed = cache.rate_limit(user_id, limit, window)
            print(f"Request {i}: Allowed? {allowed}")
            time.sleep(0.1) # Small delay

        # Test blocked request
        allowed_over = cache.rate_limit(user_id, limit, window)
        print(f"Request {limit+1}: Allowed? {allowed_over} (Should be False)")

        # Wait for window to reset (or manually clear for quick testing)
        print("Waiting 2 seconds before testing reset...")
        time.sleep(2)

        # Test after a short wait (might still be in the same window if window is large)
        allowed_reset = cache.rate_limit(user_id, limit, window)
        print(f"Request after wait: Allowed? {allowed_reset}")

        # Cleanup
        key_to_delete = f"rate_limit:{user_id}:{(int(time.time() // window) * window)}"
        cache.redis_client.delete(key_to_delete)
        print(f"Cleaned up key: {key_to_delete}")
    else:
        print("Cannot run example: Redis connection failed.")
